 "content": "from collections import Counter


def transform(grid):
    """Move the grid contents down one row; fill the vacated row with background."""
    if not grid:
        return []
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    return [[background] * len(grid[0])] + [row[:] for row in grid[:-1]]
